from pydantic import BaseModel, Field

class JudgmentDocument(BaseModel):
    title: str | None = Field(description="The title of the judgment document, as named in the document")
    cause_of_action: str | None = Field(description="The specific cause of action (案由) stated in the document")

class Parse(BaseModel):
    judgment_documents: list[JudgmentDocument]
